/* ============================================================
 * bagidea md.js — universal agent-text rendering
 * ------------------------------------------------------------
 * SECURITY INVARIANT (do not break):
 *   Text produced by agents or the user must ONLY enter the DOM via
 *   md()  (formatted markdown)   or   esc() (literal, no formatting).
 *   NEVER assign such text straight to .innerHTML — that bypasses
 *   sanitization and is an XSS hole. Every render path funnels here.
 *
 *   md(text)  = marked.parse (breaks+gfm) -> DOMPurify.sanitize (tag whitelist)
 *   esc(text) = HTML-escape for short label/name fields that must render literally
 *
 * Vendored: marked v15 (MIT) + DOMPurify 3.4 (Apache-2.0 / MPL-2.0), loaded above.
 * ============================================================ */
(function () {
  function esc(s) {
    return String(s == null ? "" : s).replace(/[&<>"]/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c];
    });
  }
  // Whitelisted tags only. No raw HTML, no <img>/<iframe>/<script>/<table>/<form>.
  // Headings kept (meeting minutes use ##); tables/images dropped (DOMPurify
  // strips the tag but keeps the text, so content is still readable).
  var ALLOWED = ["P", "BR", "STRONG", "EM", "DEL", "UL", "OL", "LI",
    "H1", "H2", "H3", "H4", "H5", "H6", "CODE", "PRE", "BLOCKQUOTE", "A", "HR"];
  function md(text) {
    if (text == null) text = "";
    var html = marked.parse(String(text), { breaks: true, gfm: true });
    return DOMPurify.sanitize(html, {
      ALLOWED_TAGS: ALLOWED,
      ALLOWED_ATTR: ["href", "title"]
    });
  }
  window.esc = esc;
  window.md = md;
})();
